import React, { useState, useEffect } from "react";
import { MapContainer, TileLayer, GeoJSON } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import Slider from "react-slider";
import "./App.css";

function App() {
  const [year, setYear] = useState(2012);
  const [geoData, setGeoData] = useState(null);
  const [activeDataType, setActiveDataType] = useState("Победитель");
  const [activeElectionLevel, setActiveElectionLevel] = useState("Госдума");
  const [activeListType, setActiveListType] = useState("Округ");
  const [mapZoom, setMapZoom] = useState(10);
  const [districtData, setDistrictData] = useState(null);
  const [uikData, setUikData] = useState(null);



  useEffect(() => {
    fetch(`/data/elections-${year}.geojson`)
      .then((res) => res.json())
      .then((data) => setGeoData(data))
      .catch((err) => console.error("Ошибка загрузки GeoJSON:", err));
  }, [year]);

  useEffect(() => {
  if (year === 2013 && activeElectionLevel === "Мэр") {
    fetch("/data/districts_with_2013_mer.geojson")
      .then(res => res.json())
      .then(data => setDistrictData(data));

    fetch("/data/united_uiks_with_final_2013_mer.geojson")
      .then(res => res.json())
      .then(data => setUikData(data));
  }
}, [year, activeElectionLevel]);

	const showDistrictLayer = year === 2013 && activeElectionLevel === "Мэр";
	const showPrecinctLayer = showDistrictLayer && mapZoom > 12;
  return (
    <div className="App">

		<div className="title-wrapper">
			<div className="title-decorated">
				<h1>Выборы Москвы</h1>
			</div>
		</div>





      {/* Слайдер */}
      <div className="slider-container">
        <label>Год: {year}</label>
        <Slider
          className="slider"
          value={year}
          min={2012}
          max={2022}
          step={1}
          onChange={setYear}
          renderTrack={(props) => <div {...props} className="slider-track" />}
          renderThumb={(props) => <div {...props} className="slider-thumb" />}
        />
      </div>

      {/* Карта + панели */}
      <div className="map-wrapper">
        <div className="map-container">
          {/* Верхняя панель */}
          <div className="top-controls">
            {["Явка", "Победитель", "Процент испорченных бюллетеней"].map(
              (label) => (
                <button
                  key={label}
                  className={activeDataType === label ? "active" : ""}
                  onClick={() => setActiveDataType(label)}
                >
                  {label}
                </button>
              )
            )}
          </div>

          {activeElectionLevel === "Госдума" && (
            <div className="center-controls">
              {["Округ", "Список"].map((label) => (
                <button
                  key={label}
                  className={activeListType === label ? "active" : ""}
                  onClick={() => setActiveListType(label)}
                >
                  {label}
                </button>
              ))}
            </div>
          )}

          {/* Боковая панель */}
          <div className="controls">
            {["Госдума", "Мосгордума", "Муниципальные", "Мэр", "Президент"].map(
              (label) => (
                <button
                  key={label}
                  className={activeElectionLevel === label ? "active" : ""}
                  onClick={() => setActiveElectionLevel(label)}
                >
                  {label}
                </button>
              )
            )}
          </div>

          {/* Leaflet карта */}
          <MapContainer
			center={[55.7558, 37.6173]}
			zoom={10}
			  className="map-container"
			  whenCreated={(map) => {
				map.on("zoomend", () => setMapZoom(map.getZoom()));
			  }}
			>
			<TileLayer
			  attribution='Tiles &copy; Esri — Esri, DeLorme, NAVTEQ'
			  url="https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Light_Gray_Base/MapServer/tile/{z}/{y}/{x}"
			/>
			{showDistrictLayer && districtData && (
			  <GeoJSON
				data={districtData}
				style={() => ({
				  color: "#000",
				  weight: showPrecinctLayer ? 2.5 : 1.5,
				  fillOpacity: showPrecinctLayer ? 0 : 0.6,
				  fillColor: "#ccc"
				})}
			  />
			)}

			{/* УИКи */}
			{showPrecinctLayer && uikData && (
			  <GeoJSON
				data={uikData}
				style={() => ({
				  color: "#333",
				  weight: 1,
				  fillOpacity: 0.7,
				  fillColor: "#bbb"
				})}
			  />
			)}
            {geoData && (
              <GeoJSON
                data={geoData}
                style={() => ({
                  color: "#007bff",
                  weight: 1,
                  fillOpacity: 0.25,
                })}
                onEachFeature={(feature, layer) => {
                  const props = feature.properties;
                  const label = props?.name || props?.id || "Участок";
                  layer.bindPopup(`<b>${label}</b>`);
                }}
              />
            )}
          </MapContainer>
        </div>
      </div>
    </div>
  );
}

export default App;
